// intent: Exercises copy_keys_equal and detect_equal_comparable by copying a JSON object whose custom key type defines operator==.
#include <nlohmann/json.hpp>
#include <map>
#include <string>
#include <iostream>

struct custom_key_with_eq {
    std::string s;
    bool operator<(const custom_key_with_eq& o) const { return s < o.s; }
    bool operator==(const custom_key_with_eq& o) const { return s == o.s; }
    operator std::string() const { return s; }
};

namespace nlohmann {
template <>
struct adl_serializer<custom_key_with_eq> {
    static void to_json(json& j, const custom_key_with_eq& k) { j = k.s; }
};
}

using custom_map = std::map<custom_key_with_eq, nlohmann::json, std::less<custom_key_with_eq>>;
using custom_json = nlohmann::basic_json<custom_map>;

int main() {
    custom_json j;
    j[custom_key_with_eq{"hello"}] = 42;
    custom_json j_copy(j);
    std::cout << j_copy.dump() << std::endl;
    return 0;
}
